  ('pouch_35g_cost', 'Мини-пакет для навески набора (35 г)', 5.06::numeric, null, '₽/шт.', 'Факт: куплено 20.10', 'Крафт с окном 10×15 см: 253 ₽ / 50 шт = 5,06 ₽ (заказ 20.10).', '2026-10-20'::date, 'импорт v1.5'),
  ('codes_per_set4x35_packs', 'Кодов маркировки на набор 4×35 г', 4::numeric, null, 'код/набор', 'Подтверждено ЧЗ', '4 кода на пачки набора 4×35 г — по одному на пачку. Код набора (КИН) на коробке — отдельно, в C71. Ответ ЧЗ SR8968218.', '2026-10-20'::date, 'импорт v1.5'),
  ('scales_cost', 'Весы', 12296::numeric, null, '₽', 'Факт: заказаны 19.10', 'Никита 20.10: весы с поверкой, 12 296 ₽.', '2026-10-20'::date, 'импорт v1.5'),
  ('kkt_cost', 'ККТ, ФН и настройка фискализации', 0::numeric, null, '₽', 'Вариант «Чеки от ЮKassa»', '«Чеки от ЮKassa»: отдельной платы за второй чек нет; закрывающий чек с кодами — только через API (поддержка ЮKassa 26.09). Тест чека с кодом ещё не проведён.', '2026-10-20'::date, 'импорт v1.5'),
  ('edo_ukep_cost', 'УКЭП/ЭДО/регистрация маркировки', 0::numeric, null, '₽', 'ЭДО Лайт, токен куплен ранее', 'Никита 20.10: ЭДО Лайт бесплатно; токен уже оплачен до выписки 14.10, в будущий бюджет не входит.', '2026-10-20'::date, 'импорт v1.5'),
  ('gtin_cost', 'GTIN / карточки товара / каталог', 0::numeric, null, '₽', 'Заявка ГС1 РУС 20.10', 'Заявка в ГС1 РУС через Нацкаталог принята 20.10: после счёта-подтверждения доступны 100 GTIN бесплатно. Сумму счёта за полное членство сверить, когда придёт.', '2026-10-20'::date, 'импорт v1.5'),
  ('inbound_delivery_first_purchase', 'Доставка основной партии', 3610.08::numeric, null, '₽', 'Формула', 'Вес закупки × входящая логистика 144 ₽/кг', '2026-10-20'::date, 'импорт v1.5'),
