  ('usd_rub', 'Курс доллара', 105::numeric, null, '₽/$', 'Подтверждено Никитой 12.10', '12.10, 13:39: эффективный курс 105 ₽/$. $1 за консультацию остаётся оценкой; конверсия до продаж неизвестна.', '2026-10-20'::date, 'импорт v1.5'),
