  ('first_order_discount', 'Скидка первого заказа I-TEA', 0.1::numeric, null, '%', 'Подтверждено', '10% на весь объём: Никита 18.10 20:50. До счёта — только 10% от базовой цены, без суммирования с 5/12/18% прайса: сочетание скидок ответом не установлено.', '2026-10-20'::date, 'импорт v1.5'),
  ('packing_loss_rate', 'Потери при фасовке и усушке', null::numeric, null, '%', 'Нет данных', 'Замерить на первой фасовке. Пока пусто — считается без потерь: из 1 кг ровно 10 пачек', '2026-10-20'::date, 'импорт v1.5'),
  ('pilot_max_loss', 'Максимальный убыток пилота — правило остановки', 30000::numeric, null, '₽', 'Предложение, не утверждено', 'Предел новых операционных потерь пилота. До20 тыс. предупредительная пауза; учитывать обязательные будущие расходы. Исторические затраты до пилота сверить отдельно.', '2026-10-20'::date, 'импорт v1.5'),
  ('acquiring_rate', 'Карты: эквайринг без НДС', 0.034::numeric, null, '%', 'Никита 13.10: 3,4%', 'НДС в 3,4% не уточнён. Пока консервативно начисляется 22% сверх комиссии. Если включён — C59=0; альтернатива на листе 12.', '2026-10-20'::date, 'импорт v1.5'),
